#include <algorithm>
#include <cmath>
#include <expected>
#include <iostream>
#include <print>
#include <string>
#include "hsv_to_rgb.h"
#include "parse_args.h"

void write_ppm_header(int width, int height) {
    std::println("P3");
    std::println("{} {}", width, height);
    std::println("255");
}

void draw_gradient(int size) {
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int r = x * 255 / size;
            int g = (size - y) * 255 / size;
            int b = 0;
            std::print("{:3d} {:3d} {:3d}", r, g, b);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

void draw_checker(int size) {
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int r = ((x + y) % 2 == 0) ? 255 : 0;
            int g = ((x + y) % 2 == 0) ? 255 : 0;
            int b = ((x + y) % 2 == 0) ? 255 : 0;
            std::print("{:3d} {:3d} {:3d}", r, g, b);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

RGB hsv_to_rgb(double h, double s, double v) {
    double c = v * s;
    double x = c * (1 - std::abs(std::fmod(h / 60.0, 2) - 1));
    double m = v - c;
    double r1 = 0;
    double g1 = 0;
    double b1 = 0;
    switch (static_cast<int>(h / 60.0) % 6) {
    case 0:
        r1 = c;
        g1 = x;
        b1 = 0;
        break;
    case 1:
        r1 = x;
        g1 = c;
        b1 = 0;
        break;
    case 2:
        r1 = 0;
        g1 = c;
        b1 = x;
        break;
    case 3:
        r1 = 0;
        g1 = x;
        b1 = c;
        break;
    case 4:
        r1 = x;
        g1 = 0;
        b1 = c;
        break;
    case 5:
        r1 = c;
        g1 = 0;
        b1 = x;
        break;
    }
    return {std::clamp(static_cast<int>((r1 + m) * 255), 0, 255),
            std::clamp(static_cast<int>((g1 + m) * 255), 0, 255),
            std::clamp(static_cast<int>((b1 + m) * 255), 0, 255)};
}

void draw_radial(int size) {
    double cx = (size - 1) / 2.0;
    double cy = (size - 1) / 2.0;
    double max_dist = std::sqrt(cx * cx + cy * cy); // ���������� �� ����
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            double dx = x - cx;
            double dy = y - cy;
            double dist = std::sqrt(dx * dx + dy * dy);

            double hue = max_dist > 0 ? (dist / max_dist) * 360.0 : 0.0;
            RGB color = hsv_to_rgb(hue, 1.0, 1.0);
            std::print("{:3d} {:3d} {:3d}", color.r, color.g, color.b);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

void generate_ppm(const Args& args) {
    write_ppm_header(args.size, args.size);
    switch (args.pattern) {
        using enum Pattern;
    case Gradient:
        draw_gradient(args.size);
        break;
    case Checker:
        draw_checker(args.size);
        break;
    case Radial:
        draw_radial(args.size);
        break;
    }
}

std::expected<Args, ParseError> parse_args(int argc, char** argv) {
    if (argc < 2) [[unlikely]]
        return std::unexpected(ParseError::kNoArg);

    int size{};
    auto [ptr, ec] = std::from_chars(argv[1], argv[1] + std::strlen(argv[1]), size);
    if (ec != std::errc{} || *ptr != '\0') [[unlikely]]
        return std::unexpected(ParseError::kBadNumber);

    std::string_view name = (argc >= 3) ? argv[2] : "gradient";
    Pattern pattern{};
    if (name == "gradient")
        pattern = Pattern::Gradient;
    else if (name == "checker")
        pattern = Pattern::Checker;
    else if (name == "radial")
        pattern = Pattern::Radial;
    else [[unlikely]]
        return std::unexpected(ParseError::kBadPattern);

    return Args{.size = size, .pattern = pattern};
}

#ifndef TEST_MODE
int main(int argc, char** argv) {
    auto args = parse_args(argc, argv);
    if (!args) [[unlikely]] {
        switch (args.error()) {
        case ParseError::kNoArg:
            std::println(stderr, "N �� �������. �������������: gen_image <N> [pattern]");
            return 66;
        case ParseError::kBadNumber:
            std::println(stderr, "N ������ ���� ����� ������ � [1; 512]; ��������: {}",
                         argc >= 2 ? argv[1] : "");
            return 64;
        case ParseError::kBadPattern:
            std::println(stderr, "����������� �������: {}. ����������: gradient, checker, radial",
                         argc >= 3 ? argv[2] : "");
            return 64;
        }
    }

    if (args->size < 1 || args->size > 512) [[unlikely]] {
        std::println(stderr, "N ������ ���� � [1; 512]; ��������: {}", args->size);
        return 64;
    }

    generate_ppm(*args);
    return 0;
}
���������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������������

