@@ -0,0 +1,31 @@
+#include "hsv_to_rgb.h"
+
+#include <math.h>
+
+static int clamp(int val, int lo, int hi) {
+    if (val < lo) return lo;
+    if (val > hi) return hi;
+    return val;
+}
