#include "hsv_to_rgb.h"

#include <math.h>

static int clamp(int val, int lo, int hi) {
    if (val < lo) return lo;
    if (val > hi) return hi;
    return val;
}

struct RGB hsv_to_rgb(double h, double s, double v) {
    double c = v * s;
    double x = c * (1.0 - fabs(fmod(h / 60.0, 2.0) - 1.0));
    double m = v - c;
    double r1 = 0, g1 = 0, b1 = 0;

    switch ((int)(h / 60.0) % 6) {
    case 0: r1 = c; g1 = x; b1 = 0; break;
    case 1: r1 = x; g1 = c; b1 = 0; break;
    case 2: r1 = 0; g1 = c; b1 = x; break;
    case 3: r1 = 0; g1 = x; b1 = c; break;
    case 4: r1 = x; g1 = 0; b1 = c; break;
    case 5: r1 = c; g1 = 0; b1 = x; break;
    }

    struct RGB result;
    result.r = (uint8_t)clamp((int)((r1 + m) * 255.0), 0, 255);
    result.g = (uint8_t)clamp((int)((g1 + m) * 255.0), 0, 255);
    result.b = (uint8_t)clamp((int)((b1 + m) * 255.0), 0, 255);
    return result;
}

#include "hsv_to_rgb.h"
#include "parse_args.h"

#include <math.h>
#include <stdio.h>

static void write_ppm_header(int width, int height) {
    printf("P3\n%d %d\n255\n", width, height);
}

static void draw_gradient(int size) {
    int max_coord = (size == 1) ? 1 : (size - 1);
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int r = x * 255 / max_coord;
            int g = (max_coord - y) * 255 / max_coord;
            int b = 0;
            printf("%3d %3d %3d", r, g, b);
            if (x + 1 < size)
                printf(" ");
        }
        printf("\n");
    }
}

static void draw_checker(int size) {
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int v = ((x + y) % 2 == 0) ? 255 : 0;
            printf("%3d %3d %3d", v, v, v);
            if (x + 1 < size)
                printf(" ");
        }
        printf("\n");
    }
}

static void draw_radial(int size) {
    double cx = (size - 1) / 2.0;
    double cy = (size - 1) / 2.0;
    double max_dist = sqrt(cx * cx + cy * cy);

    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            double dx = x - cx;
            double dy = y - cy;
            double dist = sqrt(dx * dx + dy * dy);

            double hue = (max_dist > 0.0) ? (dist / max_dist) * 360.0 : 0.0;
            struct RGB color = hsv_to_rgb(hue, 1.0, 1.0);
            printf("%3d %3d %3d", color.r, color.g, color.b);
            if (x + 1 < size)
                printf(" ");
        }
        printf("\n");
    }
}

static void generate_ppm(const struct ParseResult* args) {
    write_ppm_header(args->size, args->size);
    switch (args->pattern) {
    case PATTERN_GRADIENT:
        draw_gradient(args->size);
        break;
    case PATTERN_CHECKER:
        draw_checker(args->size);
        break;
    case PATTERN_RADIAL:
        draw_radial(args->size);
        break;
    }
}

int main(int argc, char** argv) {
    struct ParseResult args = parse_args(argc, argv);
    if (args.error != EXIT_OK) {
        switch (args.error) {
        case EXIT_NOINPUT:
            fprintf(stderr, "N не указано. Использование: gen_image <N> [pattern]\n");
            return 66;
        case EXIT_USAGE:
            if (argc >= 2) {
                char* end;
                long dummy = strtol(argv[1], &end, 10);
