                if (end == argv[1] || *end != '\0')
                    fprintf(stderr, "N должно быть целым числом в [1; 512]; получено: %s\n", argv[1]);
                else
                    fprintf(stderr, "Неизвестный паттерн: %s. Допустимые: gradient, checker, radial\n",
                            argc >= 3 ? argv[2] : "");
            }
            return 64;
        }
    }

    if (args.size < 1 || args.size > 512) {
        fprintf(stderr, "N должен быть в [1; 512]; получено: %d\n", args.size);
        return 64;
    }

    generate_ppm(&args);
    return 0;
}

