int main(void) {
    printf("--- parse_args tests ---\n");
    test_no_args();
    test_bad_number();
    test_trailing_garbage();
    test_negative_number();
    test_bad_pattern();
    test_default_pattern();
    test_checker_pattern();
    test_radial_pattern();

    printf("--- hsv_to_rgb tests ---\n");
    test_hsv_red();
    test_hsv_green();
    test_hsv_blue();
    test_hsv_yellow();
    test_hsv_cyan();
    test_hsv_magenta();
    test_hsv_360_is_red();
    test_hsv_zero_saturation();
    test_hsv_zero_value();
    test_hsv_half_saturation();

