#include <cmath>
#include <expected>
#include <print>

#include "hsv_to_rgb.h"
#include "parse_args.h"

void write_ppm_header(int width, int height) {
    std::println("P3");
    std::println("{} {}", width, height);
    std::println("255");
}

void draw_gradient(int size) {
    int max_coord = (size == 1) ? 1 : (size - 1);
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int r = x * 255 / max_coord;
            int g = (max_coord - y) * 255 / max_coord;
            int b = 0;
            std::print("{:3d} {:3d} {:3d}", r, g, b);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

void draw_checker(int size) {
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            int v = ((x + y) % 2 == 0) ? 255 : 0;
            std::print("{:3d} {:3d} {:3d}", v, v, v);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

void draw_radial(int size) {
    double cx = (size - 1) / 2.0;
    double cy = (size - 1) / 2.0;
    double max_dist = std::sqrt(cx * cx + cy * cy);
    for (int y = 0; y < size; ++y) {
        for (int x = 0; x < size; ++x) {
            double dx = x - cx;
            double dy = y - cy;
            double dist = std::sqrt(dx * dx + dy * dy);

            double hue = max_dist > 0 ? (dist / max_dist) * 360.0 : 0.0;
            RGB color = hsv_to_rgb(hue, 1.0, 1.0);
            std::print("{:3d} {:3d} {:3d}", color.r, color.g, color.b);
            if (x + 1 < size)
                std::print(" ");
        }
        std::println();
    }
}

void generate_ppm(const Args& args) {
    write_ppm_header(args.size, args.size);
    switch (args.pattern) {
        using enum Pattern;
    case Gradient:
        draw_gradient(args.size);
        break;
    case Checker:
        draw_checker(args.size);
        break;
    case Radial:
        draw_radial(args.size);
        break;
    }
}

int main(int argc, char** argv) {
    auto args = parse_args(argc, argv);
    if (!args) [[unlikely]] {
        switch (args.error()) {
        case ParseError::kNoArg:
            std::println(stderr, "N не указано. Использование: gen_image <N> [pattern]");
            return 66;
        case ParseError::kBadNumber:
            std::println(stderr, "N должно быть целым числом в [1; 512]; получено: {}",
                         argc >= 2 ? argv[1] : "");
            return 64;
        case ParseError::kBadPattern:
            std::println(stderr, "Неизвестный паттерн: {}. Допустимые: gradient, checker, radial",
                         argc >= 3 ? argv[2] : "");
            return 64;
        }
    }

    if (args->size < 1 || args->size > 512) [[unlikely]] {
        std::println(stderr, "N должен быть в [1; 512]; получено: {}", args->size);
        return 64;
    }

    generate_ppm(*args);
    return 0;
}
